versions.variantCss:
.wemd-end-card[data-variant="bytedance-end-signature"] {
  background: linear-gradient(135deg, var(--wemd-bg-soft), var(--wemd-bg-muted));
  border-radius: var(--wemd-border-radius);
  padding: 48px 32px;
  margin: 32px 0 0 0;
  text-align: center;
  border: 1px solid var(--wemd-border-soft);
}
.wemd-end-card[data-variant="bytedance-end-signature"] .wemd-ec-deco {
  color: var(--wemd-primary);
  font-size: 28px;
  margin: 0 0 16px 0;
  letter-spacing: 8px;
}
.wemd-end-card[data-variant="bytedance-end-signature"] .wemd-ec-title {
  color: var(--wemd-text-strong);
  font-size: 24px;
  font-weight: 700;
  margin: 0 0 12px 0;
}
.wemd-end-card[data-variant="bytedance-end-signature"] .wemd-ec-subtitle {
  color: var(--wemd-primary);
  font-size: 15px;
  font-weight: 500;
  font-style: italic;
  margin: 0;
}
